// Weapon system (03 §3.4 step 7, §3.8). Pure logic only: no Math.random, no Date.now,
// no cc/wx.
//
// Every weapon implements the same interface `{ id, index, tick(world, state, dt) }`
// and reads all numbers from data/weapons.js — no magic numbers in code. S2 ships
// all five weapons (raindrop / leaf_boomerang per 08 K8/L9, see their objects below).
// spore_shot rules (01 §6.1, 03 §3.8):
//   - lock the nearest living enemy (linear scan of enemies.active, ≤202);
//   - fire `count` projectiles in a fan centred on the aim direction, `spreadDeg` apart;
//   - each projectile pierces `pierce` enemies, lives `life` seconds;
//   - 无目标不进入冷却：with no enemy on the field the weapon does not consume cooldown
//     (so the first shot lands immediately once an enemy appears).
// umbrella_blades (01 §6.2): blades at angle = ω·t + 2πi/n around the player (no pool);
//   blade radius 16 × area, orbit radius × area; 单敌受击间隔 is per whole weapon
//   (enemy.hitAt[index]) and scaled by cooldown; knockback along player→enemy.
// dew_ring (01 §6.3): radius × area; every `interval × cooldown` seconds damages every
//   enemy inside; enemies inside get slow = max(slow, level slow) each step (enemy step
//   clears it, so leaving the ring restores speed immediately); no knockback.

import { WEAPONS } from './data/weapons'
import { actualDamage, actualCooldown } from './Stats'

// Shot pool object factory + reset signature used by Projectiles / SurvivorRun.
export function makeShot() {
  return {
    slot: 0,
    uid: 0,
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
    r: 6,          // 03 §3.2 弹体半径 6
    damage: 0,
    knockback: 0,
    life: 0,
    pierceLeft: 1,
    hitUids: [],
    // leaf_boomerang only (kind 'leaf'): unlimited pierce, out → back legs.
    kind: 'spore',   // 'spore' | 'leaf'
    speed: 0,
    travelLeft: 0,   // out leg: distance still to fly before turning back
    returning: false,
    catchR: 0,       // back leg: recycled once within this distance of the player
  }
}

export function resetShot(shot, { x, y, vx, vy, damage, knockback, life, pierce }) {
  shot.x = x
  shot.y = y
  shot.vx = vx
  shot.vy = vy
  shot.r = 6
  shot.damage = damage
  shot.knockback = knockback
  shot.life = life
  shot.pierceLeft = pierce
  shot.hitUids.length = 0
  shot.kind = 'spore'
  shot.speed = 0
  shot.travelLeft = 0
  shot.returning = false
  shot.catchR = 0
}

// Leaf (boomerang) shot reset: flies `distance` along (dirX, dirY), then homes back.
export function resetLeaf(shot, { x, y, dirX, dirY, speed, distance, damage, knockback, r, catchR, life }) {
  resetShot(shot, { x, y, vx: dirX * speed, vy: dirY * speed, damage, knockback, life, pierce: 0 })
  shot.r = r
  shot.kind = 'leaf'
  shot.speed = speed
  shot.travelLeft = distance
  shot.catchR = catchR
}

// Raindrop zone pool object (03 §3.5 zones 池：雨滴落点 阴影 → 伤害). The landing point is
// locked when the shadow appears (01 §6.4 落点不追踪); it resolves once world.time
// reaches `at`.
export function makeZone() {
  return { slot: 0, uid: 0, kind: 'raindrop', x: 0, y: 0, r: 0, damage: 0, knockback: 0, bornAt: 0, at: 0 }
}

// Find the nearest living enemy to (px, py); linear scan (03 §3.6). Returns the enemy
// object or null. Ties resolve to the earliest active-table index (deterministic).
export function nearestEnemy(enemies, px, py) {
  let best = null
  let bestD = Infinity
  for (let i = 0; i < enemies.count; i += 1) {
    const e = enemies.active[i]
    if (e.hp <= 0) continue
    const dx = e.x - px
    const dy = e.y - py
    const d = dx * dx + dy * dy
    if (d < bestD) {
      bestD = d
      best = e
    }
  }
  return best
}

// Build the fan of aim angles: `count` rays centred on `baseAngle`, `spreadRad` apart.
// count=1 → [base]; count=2 → base ± spread/2; count=3 → base-spread, base, base+spread.
export function fanAngles(baseAngle, count, spreadRad, out) {
  const start = baseAngle - (spreadRad * (count - 1)) / 2
  for (let i = 0; i < count; i += 1) {
    out[i] = start + spreadRad * i
  }
  return out
}

const DEG = Math.PI / 180

// spore_shot weapon object.
export const sporeShot = {
  id: 'spore_shot',
  index: WEAPONS.spore_shot.index,
  tick(world, state, dt) {
    // Cooldown counts down only while there is a target (无目标不进入冷却).
    const target = nearestEnemy(world.enemies, world.player.x, world.player.y)
    if (!target) return
    if (state.cooldown > 0) {
      state.cooldown -= dt
      return
    }
    const lvl = WEAPONS.spore_shot.levels[clampLevel('spore_shot', state.level)]
    const might = world.stats.might
    const damage = actualDamage(lvl.damage, might)
    const baseAngle = Math.atan2(target.y - world.player.y, target.x - world.player.x)
    const spreadRad = (WEAPONS.spore_shot.spreadDeg || 0) * DEG
    const angles = fanAngles(baseAngle, lvl.count, spreadRad, world.weaponAngleBuf)
    let fired = 0
    for (let i = 0; i < lvl.count; i += 1) {
      const shot = world.shots.acquire()
      if (!shot) break // pool full → fire fewer this tick (diag counted by caller)
      const a = angles[i]
      resetShot(shot, {
        x: world.player.x,
        y: world.player.y,
        vx: Math.cos(a) * lvl.speed,
        vy: Math.sin(a) * lvl.speed,
        damage,
        knockback: lvl.knockback,
        life: lvl.life,
        pierce: lvl.pierce,
      })
      fired += 1
    }
    if (fired > 0) {
      // Only consume cooldown when at least one shot actually launched.
      state.cooldown = actualCooldown(lvl.cooldown, world.stats.cooldownMul)
      world.events.push({ type: 'weaponFired', id: 'spore_shot' })
    }
  },
}

function clampLevel(id, level) {
  const max = WEAPONS[id].levels.length
  if (!(level >= 1)) return 0
  if (level > max) return max - 1
  return level - 1
}

// Runtime state for one equipped weapon (run.weapons entry). All fields exist up front
// so no weapon allocates during the step loop. bladeX/bladeY/bladeCount/bladeR and
// ringR are written by the weapon each step for the presentation layer to read.
export const MAX_BLADES = 8
export function makeWeaponState(id, level = 1) {
  return {
    id,
    level,
    cooldown: 0, // spore_shot: seconds until next volley; dew_ring: seconds until next pulse
    bladeCount: 0,
    bladeR: 0,
    bladeX: new Float64Array(MAX_BLADES),
    bladeY: new Float64Array(MAX_BLADES),
    ringR: 0,
  }
}

// Exact circle test against grid candidates + the large list. Writes matching enemies
// into world.hitBuf (reused array) and returns the count. Dead/inactive are skipped.
export function enemiesInCircle(world, x, y, r) {
  const enemies = world.enemies
  const grid = world.grid
  const buf = world.queryBuf
  const out = world.hitBuf || (world.hitBuf = new Array(enemies.capacity))
  let count = 0
  const n = grid.queryCircle(x, y, r, buf)
  for (let k = 0; k < n; k += 1) {
    const e = enemies.items[buf[k]]
    if (!enemies.isActive(e) || e.hp <= 0) continue
    const rr = r + e.r
    const dx = e.x - x
    const dy = e.y - y
    if (dx * dx + dy * dy > rr * rr) continue
    out[count++] = e
  }
  const large = grid.large
  for (let k = 0; k < large.length; k += 1) {
    const e = large[k]
    if (!enemies.isActive(e) || e.hp <= 0) continue
    const rr = r + e.r
    const dx = e.x - x
    const dy = e.y - y
    if (dx * dx + dy * dy > rr * rr) continue
    out[count++] = e
  }
  return count
}

// umbrella_blades weapon object (01 §6.2).
export const umbrellaBlades = {
  id: 'umbrella_blades',
  index: WEAPONS.umbrella_blades.index,
  tick(world, state) {
    const def = WEAPONS.umbrella_blades
    const lvl = def.levels[clampLevel('umbrella_blades', state.level)]
    const area = world.stats.areaMul
    const orbit = lvl.orbitRadius * area
    const bladeR = def.bladeRadius * area
    const omega = lvl.angularSpeedDeg * DEG
    const n = Math.min(lvl.count, MAX_BLADES)
    const px = world.player.x
    const py = world.player.y
    const t = world.time
    const damage = actualDamage(lvl.damage, world.stats.might)
    const interval = actualCooldown(lvl.hitInterval, world.stats.cooldownMul)
    const idx = this.index
    state.bladeCount = n
    state.bladeR = bladeR
    for (let i = 0; i < n; i += 1) {
      const a = omega * t + (2 * Math.PI * i) / n
      const bx = px + Math.cos(a) * orbit
      const by = py + Math.sin(a) * orbit
      state.bladeX[i] = bx
      state.bladeY[i] = by
      const m = enemiesInCircle(world, bx, by, bladeR)
      for (let k = 0; k < m; k += 1) {
        const e = world.hitBuf[k]
        // Per-weapon gate: a second blade touching the same enemy this step is ignored.
        if (t < e.hitAt[idx]) continue
        e.hitAt[idx] = t + interval
        e.hp -= damage
        e.lastHitTime = t
        const push = lvl.knockback * (1 - e.kbRes)
        if (push > 0) {
          const dx = e.x - px
          const dy = e.y - py
          const d = Math.hypot(dx, dy) || 1
          e.kbX += (dx / d) * push
          e.kbY += (dy / d) * push
        }
      }
    }
  },
}

// dew_ring weapon object (01 §6.3).
export const dewRing = {
  id: 'dew_ring',
  index: WEAPONS.dew_ring.index,
  tick(world, state, dt) {
    const lvl = WEAPONS.dew_ring.levels[clampLevel('dew_ring', state.level)]
    const r = lvl.radius * world.stats.areaMul
    state.ringR = r
    const t = world.time
    const m = enemiesInCircle(world, world.player.x, world.player.y, r)
    // Slow: take the max of all sources, never stack.
    for (let k = 0; k < m; k += 1) {
      const e = world.hitBuf[k]
      if (lvl.slow > e.slow) e.slow = lvl.slow
    }
    if (state.cooldown > 0) {
      state.cooldown -= dt
      if (state.cooldown > 0) return
    }
    const damage = actualDamage(lvl.damage, world.stats.might)
    for (let k = 0; k < m; k += 1) {
      const e = world.hitBuf[k]
      e.hp -= damage
      e.lastHitTime = t
    }
    state.cooldown += actualCooldown(lvl.interval, world.stats.cooldownMul)
  },
}

// raindrop weapon object (01 §6.4). Picks random living enemies within `range` of the
// player (several drops in one cast prefer different enemies; repeats only once every
// candidate is used), else lands at a random point 150–300 from the player. Each drop
// becomes a zone (shadow) locked at that point; Projectiles.stepZones resolves it after
// `warnSec`. Random numbers come only from world.weaponRng (`${seed}:weapon`, 03 §3.3).
export const raindrop = {
  id: 'raindrop',
  index: WEAPONS.raindrop.index,
  tick(world, state, dt) {
    if (state.cooldown > 0) {
      state.cooldown -= dt
      if (state.cooldown > 0) return
    }
    const def = WEAPONS.raindrop
    const lvl = def.levels[clampLevel('raindrop', state.level)]
    const rng = world.weaponRng
    const px = world.player.x
    const py = world.player.y
    // Candidates within range (linear scan, 03 §3.6), into the reusable hit buffer.
    const enemies = world.enemies
    const cand = world.hitBuf || (world.hitBuf = new Array(enemies.capacity))
    const range2 = def.range * def.range
    let n = 0
    for (let i = 0; i < enemies.count; i += 1) {
      const e = enemies.active[i]
      if (e.hp <= 0) continue
      const dx = e.x - px
      const dy = e.y - py
      if (dx * dx + dy * dy <= range2) cand[n++] = e
    }
    const radius = lvl.radius * world.stats.areaMul
    const damage = actualDamage(lvl.damage, world.stats.might)
    let left = 0 // candidates not yet picked this cast live in cand[0..left)
    let dropped = 0
    for (let i = 0; i < lvl.count; i += 1) {
      let x
      let y
      if (n > 0) {
        if (left === 0) left = n // every candidate used → allow repeats
        const j = rng.int(0, left - 1)
        const e = cand[j]
        // Move the pick out of the unpicked range (partial Fisher–Yates).
        cand[j] = cand[left - 1]
        cand[left - 1] = e
        left -= 1
        x = e.x
        y = e.y
      } else {
        const a = rng.next() * Math.PI * 2
        const d = rng.range(def.fallbackMin, def.fallbackMax)
        x = px + Math.cos(a) * d
        y = py + Math.sin(a) * d
      }
      const z = world.zones.acquire()
      if (!z) {
        dropped += 1
        continue
      }
      z.kind = 'raindrop'
      z.x = x
      z.y = y
      z.r = radius
      z.damage = damage
      z.knockback = lvl.knockback
      z.bornAt = world.time
      z.at = world.time + def.warnSec
      world.events.push({ type: 'raindropWarn', x, y, r: radius })
    }
    if (dropped > 0 && world.diag) world.diag.dropped.zones = (world.diag.dropped.zones || 0) + dropped
    state.cooldown += actualCooldown(lvl.cooldown, world.stats.cooldownMul)
    world.events.push({ type: 'weaponFired', id: 'raindrop' })
  },
}

// leaf_boomerang weapon object (01 §6.5): throws `count` leaves along the player's
// facing, `spreadDeg` apart; max distance × area. Flight/return/hit rules live in
// Projectiles.stepProjectiles (kind 'leaf'). Pool full → fewer leaves (diag counted).
export const leafBoomerang = {
  id: 'leaf_boomerang',
  index: WEAPONS.leaf_boomerang.index,
  tick(world, state, dt) {
    if (state.cooldown > 0) {
      state.cooldown -= dt
      if (state.cooldown > 0) return
    }
    const def = WEAPONS.leaf_boomerang
    const lvl = def.levels[clampLevel('leaf_boomerang', state.level)]
    const p = world.player
    const fx = Number.isFinite(p.dirX) ? p.dirX : 0
    const fy = Number.isFinite(p.dirY) ? p.dirY : -1
    const base = Math.atan2(fy, fx)
    const angles = fanAngles(base, lvl.count, def.spreadDeg * DEG, world.weaponAngleBuf)
    const damage = actualDamage(lvl.damage, world.stats.might)
    const distance = lvl.maxDistance * world.stats.areaMul
    let fired = 0
    for (let i = 0; i < lvl.count; i += 1) {
      const shot = world.shots.acquire()
      if (!shot) {
        if (world.diag) world.diag.dropped.shots = (world.diag.dropped.shots || 0) + (lvl.count - i)
        break
      }
      resetLeaf(shot, {
        x: p.x,
        y: p.y,
        dirX: Math.cos(angles[i]),
        dirY: Math.sin(angles[i]),
        speed: lvl.speed,
        distance,
        damage,
        knockback: lvl.knockback,
        r: def.leafRadius,
        catchR: def.catchRadius,
        life: def.maxLife,
      })
      fired += 1
    }
    state.cooldown += actualCooldown(lvl.cooldown, world.stats.cooldownMul)
    if (fired > 0) world.events.push({ type: 'weaponFired', id: 'leaf_boomerang' })
  },
}

// Registry of weapon objects by id.
export const WEAPON_OBJECTS = Object.freeze({
  spore_shot: sporeShot,
  umbrella_blades: umbrellaBlades,
  dew_ring: dewRing,
  raindrop,
  leaf_boomerang: leafBoomerang,
})

// Advance all equipped weapons for one step (03 §3.4 step 7).
export function stepWeapons(world, dt) {
  for (let i = 0; i < world.weapons.length; i += 1) {
    const w = world.weapons[i]
    const obj = WEAPON_OBJECTS[w.id]
    if (obj) obj.tick(world, w, dt)
  }
}
